previewCss:
.darma-loader-darma-b7-gear-mesh { --accent: var(--loader-color, #0284c7); --accent-2: var(--loader-secondary-color, #d97706); width: var(--loader-size, 88px); height: calc(var(--loader-size, 88px) * .64); position: relative; }
.darma-loader-darma-b7-gear-mesh span { position: absolute; top: 50%; border-radius: 50%; -webkit-mask: radial-gradient(transparent 38%, #000 39%); mask: radial-gradient(transparent 38%, #000 39%); }
.darma-loader-darma-b7-gear-mesh span:nth-child(1) { left: 0; width: calc(var(--loader-size, 88px) * .58); height: calc(var(--loader-size, 88px) * .58); margin-top: calc(var(--loader-size, 88px) * -.29); background: repeating-conic-gradient(var(--accent) 0deg 20deg, transparent 20deg 40deg); animation: darma-loader-darma-b7-gear-mesh-gear-cw calc(var(--loader-speed, 1s) * 3) linear infinite; }
.darma-loader-darma-b7-gear-mesh span:nth-child(2) { right: 0; width: calc(var(--loader-size, 88px) * .42); height: calc(var(--loader-size, 88px) * .42); margin-top: calc(var(--loader-size, 88px) * -.21); background: repeating-conic-gradient(var(--accent-2) 0deg 20deg, transparent 20deg 40deg); animation: darma-loader-darma-b7-gear-mesh-gear-ccw calc(var(--loader-speed, 1s) * 3) linear infinite; }
@keyframes darma-loader-darma-b7-gear-mesh-gear-cw { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b7-gear-mesh-gear-ccw { to { transform: rotate(-360deg); } }

